import * as THREE from "three";

export interface LandmarkPoint {
  id: string;
  name: string;
  vietnameseName: string;
  category: "trailhead" | "pagoda" | "wildlife" | "nature" | "summit";
  position: [number, number, number];
  elevationMeters: number;
  distanceKm: number;
  description: string;
  highlights: string[];
  tips: string;
}

/* ------------------------------------------------------------------ *
 * Real route from OpenStreetMap (© OpenStreetMap contributors, ODbL).
 * src/data/osmRoute.json is generated by `node scripts/fetch-osm.mjs`
 * (Overpass API → shortest path Linh Ung viewpoint → Ban Co Peak).
 * OSM has no elevation for these ways, so scene height rises linearly with
 * distance toward the real summit height.
 * ------------------------------------------------------------------ */
import osmRoute from "../../data/osmRoute.json";

/** Metres of real world per scene metre. */
export const OSM_SCALE = 27.5;
const REF_LAT = osmRoute.start.lat;
const REF_LON = osmRoute.start.lon;
const KX = 111320 * Math.cos((REF_LAT * Math.PI) / 180);
const KY = 110574;
/** Scene position of the route start (Linh Ung / Bai But viewpoint). */
const ORIGIN_X = -52;
const ORIGIN_Z = 40;

export const ROUTE_LENGTH_KM = (osmRoute.mainLengthM ?? 0) / 1000;

/** OSM latitude/longitude → scene X/Z (north = -Z). */
export function latLonToScene(lat: number, lon: number): [number, number] {
  return [
    ((lon - REF_LON) * KX) / OSM_SCALE + ORIGIN_X,
    (-(lat - REF_LAT) * KY) / OSM_SCALE + ORIGIN_Z,
  ];
}

/** Scene X/Z → OSM latitude/longitude (used for live tracking on the OSM map). */
export function sceneToLatLon(x: number, z: number): [number, number] {
  return [
    -((z - ORIGIN_Z) * OSM_SCALE) / KY + REF_LAT,
    ((x - ORIGIN_X) * OSM_SCALE) / KX + REF_LON,
  ];
}

const SUMMIT_HEIGHT = 13;

function buildRoadPoints(): [number, number, number][] {
  const raw = osmRoute.main as [number, number][];
  const xz = raw.map(([lat, lon]) => latLonToScene(lat, lon));
  // cumulative real distance fraction for the height ramp
  const cum: number[] = [0];
  for (let i = 1; i < xz.length; i++) {
    cum.push(cum[i - 1] + Math.hypot(xz[i][0] - xz[i - 1][0], xz[i][1] - xz[i - 1][1]));
  }
  const total = cum[cum.length - 1] || 1;
  // Smooth the raw OSM polyline so hairpins become drivable curves (endpoints stay fixed)
  const orig = xz.map((p) => [p[0], p[1]] as [number, number]);
  for (let pass = 0; pass < 6; pass++) {
    const prev = xz.map((p) => [p[0], p[1]] as [number, number]);
    for (let i = 1; i < xz.length - 1; i++) {
      xz[i][0] = prev[i - 1][0] * 0.25 + prev[i][0] * 0.5 + prev[i + 1][0] * 0.25;
      xz[i][1] = prev[i - 1][1] * 0.25 + prev[i][1] * 0.5 + prev[i + 1][1] * 0.25;
    }
  }
  void orig;
  const pts: [number, number, number][] = [];
  let last = -Infinity;
  for (let i = 0; i < xz.length; i++) {
    if (i !== xz.length - 1 && cum[i] - last < 5) continue;
    last = cum[i];
    pts.push([xz[i][0], 0.2 + SUMMIT_HEIGHT * (cum[i] / total), xz[i][1]]);
  }
  return pts;
}

/** Real OSM road polyline in scene metres (X: West-East, Y: Elevation, Z: South-North). */
export const ROAD_CONTROL_POINTS: [number, number, number][] = buildRoadPoints();

function pointAtFraction(f: number): [number, number, number] {
  const idx = Math.min(ROAD_CONTROL_POINTS.length - 1, Math.round(f * (ROAD_CONTROL_POINTS.length - 1)));
  return ROAD_CONTROL_POINTS[idx];
}

/**
 * Short forest spur toward the Ancient Banyan Tree. Illustrative only: the real OSM
 * heritage banyan is ~9 km away on the east side of the peninsula.
 */
const BANYAN_ANCHOR = pointAtFraction(0.72);
export const BANYAN_TRAIL_POINTS: [number, number, number][] = [
  BANYAN_ANCHOR,
  [BANYAN_ANCHOR[0] - 9, BANYAN_ANCHOR[1] - 0.2, BANYAN_ANCHOR[2] - 3],
  [BANYAN_ANCHOR[0] - 18, BANYAN_ANCHOR[1] - 0.4, BANYAN_ANCHOR[2] - 6],
  [BANYAN_ANCHOR[0] - 26, BANYAN_ANCHOR[1] - 0.5, BANYAN_ANCHOR[2] - 8],
];

let cachedRoadCurve: THREE.CatmullRomCurve3 | null = null;
let cachedTrailCurve: THREE.CatmullRomCurve3 | null = null;
let cachedSampledPoints: THREE.Vector3[] | null = null;

export function getRoadCurve(): THREE.CatmullRomCurve3 {
  if (!cachedRoadCurve) {
    cachedRoadCurve = new THREE.CatmullRomCurve3(
      ROAD_CONTROL_POINTS.map(([x, y, z]) => new THREE.Vector3(x, y, z)),
      false,
      "catmullrom",
      0.45
    );
  }
  return cachedRoadCurve;
}

export function getBanyanTrailCurve(): THREE.CatmullRomCurve3 {
  if (!cachedTrailCurve) {
    cachedTrailCurve = new THREE.CatmullRomCurve3(
      BANYAN_TRAIL_POINTS.map(([x, y, z]) => new THREE.Vector3(x, y, z)),
      false,
      "catmullrom",
      0.5
    );
  }
  return cachedTrailCurve;
}

export function getSampledRoadPoints(divisions = 480): THREE.Vector3[] {
  if (!cachedSampledPoints) {
    cachedSampledPoints = getRoadCurve().getSpacedPoints(divisions);
  }
  return cachedSampledPoints;
}

/**
 * Finds the closest point on the main roadline to (x, z), returning its elevation,
 * horizontal distance, and normalized progress t in [0, 1].
 */
export function getClosestRoadInfo(x: number, z: number): {
  point: THREE.Vector3;
  distance: number;
  t: number;
} {
  const samples = getSampledRoadPoints(480);
  let bestIdx = 0;
  let bestDistSq = Infinity;

  for (let i = 0; i < samples.length; i++) {
    const dx = samples[i].x - x;
    const dz = samples[i].z - z;
    const dSq = dx * dx + dz * dz;
    if (dSq < bestDistSq) {
      bestDistSq = dSq;
      bestIdx = i;
    }
  }

  return {
    point: samples[bestIdx],
    distance: Math.sqrt(bestDistSq),
    t: bestIdx / (samples.length - 1),
  };
}

/**
 * Deterministic terrain height function for Son Tra Peninsula.
 * Blends smoothly into the roadline and Banyan trail elevations so the 3D road
 * sits naturally on the mountain slope without floating or burying.
 */
export function getTerrainHeight(x: number, z: number): number {
  // Base peninsula slope rising from South-East (sea level) to North-West (mountain peak)
  const coastalDrop = (z - 55) * -0.11 - x * 0.035;
  const ridgeWave =
    Math.sin(x * 0.055) * Math.cos(z * 0.045) * 2.2 +
    Math.sin((x - z) * 0.03) * 1.6 +
    Math.cos(x * 0.11 + z * 0.08) * 0.45;

  let naturalHeight = Math.max(-1.8, coastalDrop + ridgeWave);

  // East / South-East coastline slopes into Da Nang Bay water
  if (x > 80 || z > 74) {
    const seaFactor = Math.max((x - 80) * 0.12, (z - 74) * 0.14);
    naturalHeight -= seaFactor * 2.2;
  }

  // Natural relief: layered noise, strongest on dry land (kept out of the water line)
  const land = Math.min(1, Math.max(0, (naturalHeight + 0.4) / 2.5));
  naturalHeight +=
    land *
    (Math.sin(x * 0.21 + z * 0.13) * 0.55 +
      Math.sin(x * 0.47 - z * 0.39 + 1.7) * 0.3 +
      Math.cos(x * 0.9 + z * 0.77) * 0.12 +
      Math.sin(x * 0.05 + 2.0) * Math.cos(z * 0.07) * 1.8);

  // Blend with main roadline corridor so roadbed is flush
  const roadInfo = getClosestRoadInfo(x, z);
  const roadHalfWidth = 3.2;
  const shoulderWidth = 9.5;

  if (roadInfo.distance <= roadHalfWidth) {
    return roadInfo.point.y;
  }

  if (roadInfo.distance < shoulderWidth) {
    const alpha = (roadInfo.distance - roadHalfWidth) / (shoulderWidth - roadHalfWidth);
    const smooth = alpha * alpha * (3 - 2 * alpha);
    naturalHeight = THREE.MathUtils.lerp(roadInfo.point.y, naturalHeight, smooth);
  }

  // Also blend with the Banyan forest spur trail
  const trailSamples = getBanyanTrailCurve().getSpacedPoints(40);
  let minTrailDistSq = Infinity;
  let trailY = naturalHeight;
  for (let i = 0; i < trailSamples.length; i++) {
    const dx = trailSamples[i].x - x;
    const dz = trailSamples[i].z - z;
    const dSq = dx * dx + dz * dz;
    if (dSq < minTrailDistSq) {
      minTrailDistSq = dSq;
      trailY = trailSamples[i].y;
    }
  }
  const trailDist = Math.sqrt(minTrailDistSq);
  if (trailDist < 5.5) {
    const alpha = Math.max(0, (trailDist - 1.8) / (5.5 - 1.8));
    const smooth = alpha * alpha * (3 - 2 * alpha);
    naturalHeight = THREE.MathUtils.lerp(trailY, naturalHeight, smooth);
  }

  return naturalHeight;
}

