export const ROUTE_START: [number, number, number] = pointAtFraction(0);

/** Ten small primate encounter points spread along the trekking route. */
export const MONKEY_ROUTE_FRACTIONS = [0.14, 0.22, 0.3, 0.38, 0.46, 0.54, 0.62, 0.7, 0.79, 0.88] as const;

/** Position, tangent and right-hand side vector on the route at fraction f (0..1). */
export function getRouteFrame(f: number) {
  const curve = getRoadCurve();
  const point = curve.getPointAt(f);
  const tangent = curve.getTangentAt(f).setY(0).normalize();
  const side = new THREE.Vector3(-tangent.z, 0, tangent.x);
  return { point, tangent, side };
}
